// === Tab: mySketch ===
let w = 900, h = 900;
let s = 10;
let grid = 16;

let pal = ['#ECAA9C','#B1D1C6', '#2E5B8B', '#F2CA60', '#d4c7a3', '#DE7830', '#513C2C', '#1F3858', '#C9292E', '#bfb8a3'];

function mousePressed() {
	redraw();
}

function setup() {
  createCanvas(w, h);
	pixelDensity(2);
  noLoop();
  smooth();
  colorMode(HSB, 360, 100, 100, 100);
  strokeCap(SQUARE);
}

function drawRect(sx, sy, side, al) {
  push();
  var type1 = random();

  var ratio = random(-0.2, 1.2);

  var cc;
  if(type1 < ratio) {
    noStroke();
    cc = color( getColor(sx, sy) );
    cc.setAlpha(al);
    fill(cc);
    rect(0, 0, sx, sy, 12);

    strokeWeight(4);
    stroke(220);
    var type2 = random();
    if(side < 0.5) {
      line(-sx/2, -sy/2, sx/2, sy/2);  
    } else {
      line(sx/2, -sy/2, -sx/2, sy/2); 
    } 
  } else {
    noFill();
    strokeWeight(2);
    cc = color( getColor(sx, sy) );
    cc.setAlpha(al);
    stroke(cc);

    var kx = sx;
    var ky = sy;

    rect(0, 0, kx, ky, 5);
    rect(0, 0, kx*0.8, ky*0.8, 5);
    rect(0, 0, kx*0.6, ky*0.6, 5);
    rect(0, 0, kx*0.4, ky*0.4, 5);
  }

  pop();
}

let g = s*10;
let gr = g * 0.5;
let ratio = 0.85;

function draw() {
  background(220);
  rectMode(CENTER);

  var pp = s*4;
  drawGaze(w/2, h/2, 100);
  drawGaze(pp, pp, 80);
  drawGaze(w-pp, pp, 80);
  drawGaze(pp, h-pp, 80);
  drawGaze(w-pp, h-pp, 80);


  drawGrids();
  drawFrame();
}

function drawGaze(cx, cy, al)
{
  shuffle(pal, true);
  noiseSeed(random(100));

  var nx, ny;
  var preX1, preX2, preY1, preY2, kx, ky;

  push();
  translate(cx, cy);
  rotate(PI/4);

  // center
  drawRect(gr, gr, 1, al);
  // rect(0, 0, gr, gr, 10);

  // -----------------------------------------//
  preX1 = gr;
  push();
  for(let ix = 0; ix < 10; ix++) {
    kx = preX1 * ratio;
    translate(preX1, 0);
    drawRect(kx, gr, random(), al);
    // rect(0, 0, kx, gr, 10);
    preX1 = kx;
  }
  pop();
  // -----------------------------------------//

  // -----------------------------------------//
  preX2 = gr;
  push();
  for(let ix = 0; ix < 10; ix++) {
    kx = preX2 * ratio;
    translate(-preX2, 0);
    drawRect(kx, gr, random(), al);
    // rect(0, 0, kx, gr, 10);
    preX2 = kx;
  }
  pop();
  // -----------------------------------------//

  // -----------------------------------------//
  preY1 = gr;
  push();
  for(let iy = 0; iy < 10; iy++) {

    ky = preY1 * ratio;
    translate(0, preY1);

    drawRect(gr, ky, random(), al);
    // rect(0,0, gr, ky, 10);

    preX1 = gr;
    push();
    for(let ix = 0; ix < 10; ix++) {
      kx = preX1 * ratio;
      translate(preX1, 0);
      drawRect(kx, ky, 1, al);
      // rect(0, 0, kx, ky, 10);
      preX1 = kx;
    }
    pop();

    preX2 = gr;
    push();
    for(let ix = 0; ix < 10; ix++) {
      kx = preX2 * ratio;
      translate(-preX2, 0);
      drawRect(kx, ky, 0, al);
      // rect(0, 0, kx, ky, 10);
      preX2 = kx;
    }
    pop();

    preY1 = ky;
  }
  pop();
  // -----------------------------------------//


  // -----------------------------------------//
  preY1 = gr;
  push();
  for(let iy = 0; iy < 10; iy++) {

    ky = preY1 * ratio;
    translate(0, -preY1);

    drawRect(gr, ky, random(), al);
    // rect(0,0, gr, ky, 10);


    preX1 = gr;
    push();
    for(let ix = 0; ix < 10; ix++) {
      kx = preX1 * ratio;
      translate(preX1, 0);
      drawRect(kx, ky, 0, al);
      // rect(0, 0, kx, ky, 10);
      preX1 = kx;
    }
    pop();

    preX2 = gr;
    push();
    for(let ix = 0; ix < 10; ix++) {
      kx = preX2 * ratio;
      translate(-preX2, 0);
      drawRect(kx, ky, 1, al);
      // rect(0, 0, kx, ky, 10);
      preX2 = kx;
    }
    pop();

    preY1 = ky;
  }
  pop();
  // -----------------------------------------//


  pop();
}
// ------------------------------------- //
// ------------------------------------- //
// ------------------------------------- //

function drawGrids() {
  stroke(0,0,10,100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for(let i = 0; i < ty; i++) {
    cy = i * s;
    for(let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  } 
}

function drawFrame() {
  var s = 10;
  rectMode(CENTER);
  noStroke();
  fill(220);

  rect(s*2-1, h/2, s*4, h);
  rect(w-s*2+1, h/2, s*4, h);

  rect(w/2, s*2-1, w, s*4);
  rect(w/2, h-s*2+1, w, s*4);
}

function getColor(x, y) {
  bb = 1;
  var cc = noise(x/bb, y/bb);
  var l = pal.length;

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l) {
    return pal[1];
  } else if (cc < 3/l) {
    return pal[2];
  } else if (cc < 4/l) {
    return pal[3];
  } else if (cc < 5/l) {
    return pal[4];
  } else if (cc < 6/l) {
    return pal[5];
  } else if (cc < 7/l) {
    return pal[6];
  } else if (cc < 8/l) {
    return pal[7];
  } else if (cc < 9/l) {
    return pal[8];
  } else {
    return pal[9];
  }
}

